'use strict';
/**
 * Real PlayCanvas v2 WebGL2 browser smoke test.
 * No screenshots generated by AI. Browser render is the acceptance test.
 */
const fs=require('node:fs');
const path=require('node:path');
const http=require('node:http');
const {execFileSync}=require('node:child_process');
const {chromium}=require('playwright-core');
const ROOT=path.resolve(__dirname,'..');
function executable(){
  for(const file of [
    process.env.CHROME_PATH,
    '/usr/bin/chromium','/usr/bin/google-chrome',
    '/usr/bin/chromium-browser'
  ])if(file&&fs.existsSync(file))return file;
  return execFileSync('which',['chromium'],{encoding:'utf8'}).trim();
}
const mime={
  '.html':'text/html; charset=utf-8',
  '.js':'text/javascript; charset=utf-8',
  '.css':'text/css; charset=utf-8',
  '.png':'image/png',
  '.glb':'model/gltf-binary'
};
const server=http.createServer((req,res)=>{
  let url;
  try{url=new URL(req.url,'http://localhost');}
  catch(e){res.writeHead(400);res.end('Bad URL');return;}
  const target=path.resolve(ROOT,'.'+decodeURIComponent(url.pathname));
  if(!target.startsWith(ROOT+path.sep)){
    res.writeHead(403);res.end('Forbidden');return;
  }
  fs.stat(target,(error,stat)=>{
    if(error||!stat.isFile()){
      res.writeHead(404);res.end('Not Found');return;
    }
    res.writeHead(200,{'Content-Type':mime[path.extname(target)]||
      'application/octet-stream'});
    fs.createReadStream(target).pipe(res);
  });
});
async function main(){
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const url='http://127.0.0.1:'+server.address().port+
    '/playcanvas-house.html';
  const browser=await chromium.launch({
    executablePath:executable(),
    headless:true,
    args:[
      '--no-sandbox','--disable-dev-shm-usage',
      '--enable-unsafe-swiftshader','--use-gl=angle',
      '--use-angle=swiftshader'
    ]
  });
  const output=path.join(ROOT,'tests','screenshots');
  fs.mkdirSync(output,{recursive:true});
  try{
    const desktop=await browser.newPage({
      viewport:{width:1440,height:900},deviceScaleFactor:1
    });
    const errors=[];
    desktop.on('pageerror',err=>errors.push(err.message));
    desktop.on('requestfailed',req=>{
      if(/playcanvas@|playcanvas-toy-house\.js/.test(req.url()))
        errors.push(req.url()+': '+req.failure()?.errorText);
    });
    await desktop.goto(url,{waitUntil:'domcontentloaded',timeout:50000});
    try{
      await desktop.waitForFunction(
        ()=>document.body.dataset.pcReady==='true'&&
          document.body.dataset.pcRendered==='true',
        null,{timeout:50000}
      );
    }catch(error){
      const state=await desktop.evaluate(()=>({
        data:{...document.body.dataset},
        errorText:document.querySelector('#loading')?.textContent,
        errorStack:document.body.dataset.pcErrorStack,
        canvas:!!document.querySelector('#playcanvas')
      })).catch(e=>({error:String(e)}));
      throw Error('PlayCanvas did not start: '+JSON.stringify(state)+
        ' JS: '+errors.join('; '));
    }
    if(errors.length)throw Error('PlayCanvas JS request errors: '+
      errors.join('; '));
    const before=await desktop.evaluate(()=>({
      engine:document.body.dataset.pcEngine,
      version:document.body.dataset.pcVersion,
      ready:document.body.dataset.pcReady,
      light:document.body.dataset.pcLight,
      view:document.body.dataset.pcView,
      car:document.body.dataset.pcCarSource,
      context:!!document.getElementById('playcanvas').getContext('webgl2'),
      hero:document.body.dataset.pcHeroAsset,
      shingles:document.body.dataset.pcRoofSystem,
      foliage:document.body.dataset.pcFoliageSystem,
      clapboards:Number(document.body.dataset.pcHouseClapboards||0)
    }));
    if(before.engine!=='PlayCanvas'||before.version!=='2.23.3'||
      before.light!=='table'||before.view!=='three-quarter'||
      !before.context||
      before.hero!=='molded-geometry-v3'||
      before.shingles!=='batched-individual-shingles'||
      before.foliage!=='triangulated-branch-leaves'||
      before.clapboards<20){
      throw Error('Unexpected desktop PlayCanvas engine state '+
        JSON.stringify(before));
    }
    await desktop.waitForTimeout(650);
    await desktop.screenshot({
      path:path.join(output,'playcanvas-toy-house-desktop.png'),
      animations:'disabled'
    });
    await desktop.locator('button[data-light="studio"]').click();
    await desktop.locator('button[data-view="front"]').click();
    if(await desktop.locator('body').getAttribute('data-pc-light')!=='studio'||
      await desktop.locator('body').getAttribute('data-pc-view')!=='front'){
      throw Error('PlayCanvas lighting or front view did not update');
    }
    await desktop.locator('button[data-view="detail"]').click();
    if(await desktop.locator('body').getAttribute('data-pc-view')!=='detail'){
      throw Error('Close macro detail camera was not activated');
    }
    await desktop.screenshot({
      path:path.join(output,'playcanvas-toy-house-detail.png'),
      animations:'disabled'
    });
    await desktop.locator('button[data-light="table"]').click();
    await desktop.locator('button[data-view="top"]').click();
    await desktop.screenshot({
      path:path.join(output,'playcanvas-toy-house-overhead.png'),
      animations:'disabled'
    });
    console.log('PASS PlayCanvas native desktop engine, WebGL2 canvas and controls',
      JSON.stringify(before));
    await desktop.close();

    const mobile=await browser.newContext({
      viewport:{width:390,height:844},deviceScaleFactor:2,
      isMobile:true,hasTouch:true
    });
    const phone=await mobile.newPage();
    const mobileErrors=[];
    phone.on('pageerror',error=>mobileErrors.push(error.message));
    await phone.goto(url,{waitUntil:'domcontentloaded',timeout:50000});
    await phone.waitForFunction(
      ()=>document.body.dataset.pcReady==='true'&&
        document.body.dataset.pcRendered==='true',
      null,{timeout:50000}
    );
    if(mobileErrors.length)
      throw Error('Mobile PlayCanvas JS '+mobileErrors.join('; '));
    const mobileState=await phone.evaluate(()=>({
      engine:document.body.dataset.pcEngine,
      ready:document.body.dataset.pcReady,
      width:document.querySelector('#playcanvas').clientWidth,
      height:document.querySelector('#playcanvas').clientHeight,
      hero:document.body.dataset.pcHeroAsset,
      cameraTextVisible:getComputedStyle(document.querySelector('.overlay h1')).display!=='none',
      viewportHeight:document.querySelector('.viewer').clientHeight
    }));
    if(mobileState.engine!=='PlayCanvas'||mobileState.width<300||
      mobileState.height<350||
      mobileState.hero!=='molded-geometry-v3'||
      mobileState.cameraTextVisible)throw Error('Bad phone canvas or full view: '+
      JSON.stringify(mobileState));
    await phone.screenshot({
      path:path.join(output,'playcanvas-toy-house-mobile.png'),
      animations:'disabled'
    });
    await phone.locator('button[data-light="studio"]').tap();
    await phone.locator('button[data-view="top"]').tap();
    if(await phone.locator('body').getAttribute('data-pc-light')!=='studio'||
      await phone.locator('body').getAttribute('data-pc-view')!=='top')
      throw Error('Mobile PlayCanvas touch UI is broken');
    console.log('PASS iPhone-sized touch PlayCanvas preview',
      JSON.stringify(mobileState));
    await mobile.close();
  }finally{
    await browser.close();
    await new Promise(resolve=>server.close(resolve));
  }
}
main().then(
  ()=>console.log('PASS PlayCanvas WebGL2 miniature house prototype'),
  err=>{console.error(err.stack||err);process.exitCode=1;}
);
